`endif

    assign dbg_pc_o = dut.u_ibex.instr_addr;

    // ── Boot ROM load ──────────────────────────────────────────────────
    // Load the bus-walk test program into the CPU's local boot ROM. Same
    // mechanism as the smoke test (one-shot always-block on first posedge,
    // works around top-down initial-block ordering races).
    reg test_program_loaded = 1'b0;
    always @(posedge clk_i) begin
        if (!test_program_loaded) begin
            $readmemh("busread.hex", dut.u_ibex.boot_rom);
            $display("[tb_buswalk] loaded busread.hex; boot_rom[0]=%08h", dut.u_ibex.boot_rom[0]);
            test_program_loaded <= 1'b1;
        end
    end

endmodule